<?php
require_once "db.php"; require_login(); $uid=(int)$_SESSION["user_id"]; $error="";
if ($_SERVER["REQUEST_METHOD"]==="POST") {
    if (isset($_POST["add_contact"])) {
        $name=trim($_POST["contact_name"]??""); $phone=trim($_POST["phone"]??""); $rel=trim($_POST["relationship"]??"");
        if($name==="" || !preg_match('/^[0-9+\-\s()]{7,20}$/',$phone)) $error="Enter a contact name and valid phone number.";
        else { $stmt=$conn->prepare("INSERT INTO emergency_contacts(user_id,contact_name,phone,relationship) VALUES(?,?,?,?)"); $stmt->bind_param("isss",$uid,$name,$phone,$rel); $stmt->execute(); flash("Emergency contact added."); header("Location: contacts.php"); exit; }
    } elseif(isset($_POST["primary_id"])) {
        $id=(int)$_POST["primary_id"]; $stmt=$conn->prepare("UPDATE emergency_contacts SET is_primary=(id=?) WHERE user_id=?"); $stmt->bind_param("ii",$id,$uid); $stmt->execute(); flash("Primary contact updated."); header("Location: contacts.php"); exit;
    } elseif(isset($_POST["delete_id"])) {
        $id=(int)$_POST["delete_id"]; $stmt=$conn->prepare("DELETE FROM emergency_contacts WHERE id=? AND user_id=?"); $stmt->bind_param("ii",$id,$uid); $stmt->execute(); flash("Contact deleted."); header("Location: contacts.php"); exit;
    }
}
$stmt=$conn->prepare("SELECT id,contact_name,phone,relationship,is_primary,created_at FROM emergency_contacts WHERE user_id=? ORDER BY is_primary DESC,id DESC"); $stmt->bind_param("i",$uid); $stmt->execute(); $rows=$stmt->get_result();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Emergency Contacts | SafeHer</title><link rel="stylesheet" href="style.css"></head><body class="app-page">
<aside class="sidebar"><a class="brand" href="dashboard.php"><span class="brand-icon">✦</span> SafeHer</a><div class="side-label">WORKSPACE</div><a class="side-link" href="dashboard.php">▦ <span>Dashboard</span></a><a class="side-link active" href="contacts.php">♡ <span>Emergency contacts</span></a><a class="side-link" href="alert_history.php">◷ <span>Alert history</span></a><a class="side-link" href="tools.php">☎ <span>Safety tools</span></a><a class="side-link" href="profile.php">☺ <span>My profile</span></a><?php if(($_SESSION["role"]??"")==="admin") echo '<a class="side-link" href="admin.php">♙ <span>Admin panel</span></a>'; ?><div class="side-bottom"><div class="avatar"><?=e(strtoupper(substr($_SESSION["name"],0,1)))?></div><div><b><?=e($_SESSION["name"])?></b><small>Personal account</small></div><a class="logout" href="logout.php">↗</a></div></aside>
<main class="app-main"><header class="topbar"><div><span class="eyebrow">YOUR TRUSTED CIRCLE</span><h1>Emergency contacts <span>♡</span></h1><p class="muted">Keep the people you trust close.</p></div><a class="btn btn-small" href="dashboard.php">← Dashboard</a></header><?php show_flash(); ?><?php if($error) echo '<div class="flash error">'.e($error).'</div>'; ?>
<div class="content-grid contacts-layout"><section class="panel"><div class="panel-head"><div><h3>Add a trusted contact</h3><p class="muted">Only add people you trust.</p></div></div><form method="post" class="stack-form"><label>Contact name<input name="contact_name" maxlength="100" required placeholder="e.g. Amma"></label><label>Phone number<input name="phone" maxlength="20" required placeholder="+91 98765 43210"></label><label>Relationship<select name="relationship"><option value="">Select relationship</option><option>Family</option><option>Friend</option><option>Colleague</option><option>Neighbour</option><option>Other</option></select></label><button class="btn full" name="add_contact" value="1">＋ Save contact</button></form></section>
<section class="panel"><div class="panel-head"><div><h3>Your trusted people</h3><p class="muted"><?=$rows->num_rows?> saved contact(s)</p></div></div><?php if($rows->num_rows): while($r=$rows->fetch_assoc()): ?><div class="contact-row"><div class="contact-avatar"><?=e(strtoupper(substr($r["contact_name"],0,1)))?></div><div class="contact-info"><b><?=e($r["contact_name"])?> <?=$r["is_primary"]?"<span class=\"pill resolved\">★ Primary</span>":""?></b><small><?=e($r["relationship"] ?: "Trusted contact")?></small><a href="tel:<?=e($r["phone"])?>"><?=e($r["phone"])?></a></div><?php if(!$r["is_primary"]): ?><form method="post"><input type="hidden" name="primary_id" value="<?=$r["id"]?>"><button class="text-btn" title="Make primary">☆ Primary</button></form><?php endif; ?><form method="post" onsubmit="return confirm('Delete this contact?')"><input type="hidden" name="delete_id" value="<?=$r["id"]?>"><button class="icon-btn danger" title="Delete contact" aria-label="Delete contact">×</button></form></div><?php endwhile; else: ?><div class="empty-state">♡<p>No contacts added yet.</p><small>Use the form to add someone you trust.</small></div><?php endif; ?></section></div><p class="safety-disclaimer">Saved contacts are stored in this portal. Saving a contact does not automatically notify them during an SOS.</p></main></body></html>